def solve(nums):
    n = len(nums)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1
    for i in range(n):
        num = abs(nums[i])
        if num <= n and nums[num - 1] > 0:
            nums[num - 1] *= -1
    for i in range(n):
        if nums[i] > 0:
            return i + 1
    return n + 1

